function home(){return '<section class="hero"><div class="hero-copy"><p class="eyebrow">PLATAFORMA DE CONOCIMIENTO INDUSTRIAL</p><h1>El conocimiento<br>que mueve <em>la planta.</em></h1><p>DammPulse conecta experiencia, equipos y aprendizaje. Encuentra información, registra incidencias y convierte el conocimiento experto en recursos reutilizables.</p><div style="display:flex;gap:9px;margin-top:22px;flex-wrap:wrap"><button class="btn green" data-go="machines">Explorar equipos ↗</button><button class="btn" data-go="assistant">Hablar con el asistente</button></div></div><div class="hero-mark">360°</div></section>'+shellStats()+'<section class="pro-dashboard"><div class="dashboard-welcome"><div><p class="eyebrow">TU ESPACIO DAMTARIK</p><h2>Hoy también se aprende algo nuevo.</h2><p>Un vistazo rápido a la actividad y a tu siguiente paso.</p></div><span class="dashboard-live"><i></i> EXPERIENCIA DEMO</span></div><div class="dashboard-cards"><article class="dashboard-card dashboard-challenge"><div class="dashboard-card-top"><span>RETO DEL DÍA</span><span class="challenge-mark">✦</span></div><h3>Detecta antes de que pare.</h3><p>Aprende a reconocer señales tempranas en los equipos de producción.</p><button class="btn gold small" data-go="academy">Empezar reto →</button><div class="challenge-decoration">01</div></article><article class="dashboard-card dashboard-progress"><div class="dashboard-card-top"><span>TU PROGRESO</span><span class="progress-label">RUTA DE APRENDIZAJE</span></div><div class="progress-ring"><div><strong>3</strong><small>módulos demo</small></div></div><h3>El conocimiento se construye paso a paso.</h3><button class="text-link" data-go="academy">Continuar aprendiendo →</button></article><article class="dashboard-card dashboard-shortcuts"><div class="dashboard-card-top"><span>ACCESO RÁPIDO</span><span>↗</span></div><a href="#machines"><span>▦</span><div><b>Explorar equipos</b><small>Fichas y documentación</small></div><i>→</i></a><a href="#incidents"><span>◉</span><div><b>Registrar incidencia</b><small>Seguimiento de avisos</small></div><i>→</i></a><a href="#knowledge"><span>✳</span><div><b>Compartir conocimiento</b><small>Experiencia experta</small></div><i>→</i></a></article></div></section><div class="panel-head"><div><p>ESPACIO DE TRABAJO</p><h2>¿Qué necesitas hacer?</h2></div></div><section class="quick-grid"><a class="quick-card" href="#machines"><span class="q-icon">▦</span><strong>Equipos y QR</strong><small>Ficha contextual de cada activo</small></a><a class="quick-card" href="#incidents"><span class="q-icon">◉</span><strong>Incidencias</strong><small>Registro y seguimiento de avisos</small></a><a class="quick-card" href="#academy"><span class="q-icon">▤</span><strong>Academia</strong><small>Formación y evaluación breve</small></a><a class="quick-card" href="#knowledge"><span class="q-icon">✳</span><strong>Conocimiento experto</strong><small>Captura, revisión y publicación</small></a></section><section class="action-launcher"><div class="action-launcher-head"><div><p class="eyebrow">ATAJOS DAMTARIK</p><h2>Acciones rápidas</h2><span>Entra directamente a lo que necesitas.</span></div><span class="launcher-spark">✦</span></div><div class="action-launcher-grid"><button class="action-launcher-btn" data-go="qr"><span class="action-launcher-icon">▦</span><span class="action-launcher-copy"><strong>Generar QR</strong><small>Crea un código para una ficha demo</small></span><i>→</i></button><button class="action-launcher-btn" data-go="assistant"><span class="action-launcher-icon">✧</span><span class="action-launcher-copy"><strong>DAM Bot</strong><small>Consulta el asistente virtual</small></span><i>→</i></button><button class="action-launcher-btn" data-go="products"><span class="action-launcher-icon">◈</span><span class="action-launcher-copy"><strong>Catálogo Damm</strong><small>Explora las fichas de producto</small></span><i>→</i></button><button class="action-launcher-btn" data-go="academy"><span class="action-launcher-icon">▤</span><span class="action-launcher-copy"><strong>Mi formación</strong><small>Continúa tus módulos</small></span><i>→</i></button><button class="action-launcher-btn" data-go="knowledge"><span class="action-launcher-icon">✳</span><span class="action-launcher-copy"><strong>Compartir experiencia</strong><small>Consulta conocimiento experto</small></span><i>→</i></button><button class="action-launcher-btn" data-go="incidents"><span class="action-launcher-icon">＋</span><span class="action-launcher-copy"><strong>Nueva incidencia</strong><small>Registra un aviso de demostración</small></span><i>→</i></button></div></section><section class="grid-2"><article class="panel"><div class="panel-head"><div><p>ACTIVOS</p><h2>Equipos destacados</h2></div><button class="text-link" data-go="machines">Ver todos →</button></div><div class="machine-list">'+machines.slice(0,3).map(m=>'<div class="machine-row"><div class="row-main"><strong>'+esc(m.name)+'</strong><small>'+m.id+' · '+esc(m.area)+'</small></div>'+badge(m.state)+'</div>').join("")+'</div></article><article class="panel"><div class="panel-head"><div><p>ACTIVIDAD</p><h2>Últimos avisos</h2></div><button class="text-link" data-go="incidents">Ver registro →</button></div><div class="incident-list">'+incidents.map(i=>'<div class="incident-row"><div class="row-main"><strong>'+esc(i.title)+'</strong><small>'+i.id+' · '+i.machine+'</small></div>'+badge(i.state)+'</div>').join("")+'</div></article></section><div class="safety-note">Entorno académico. Los activos e incidencias son ficticios. No utilizar esta demo para operar, mantener o reparar equipos reales.</div>'}
function machinesPage(){return head("GESTIÓN DE ACTIVOS","Equipos y documentación","Localiza un equipo por nombre, código o área. Cada ficha incluye un QR contextual.")+'<div class="filter-row"><label class="searchbar" style="flex:1">⌕ <input id="machine-search" placeholder="Buscar equipo, código o área…"></label><select class="select" id="area-filter" style="max-width:190px"><option value="">Todas las áreas</option>'+[...new Set(machines.map(m=>m.area))].map(x=>'<option>'+x+'</option>').join("")+'</select></div><div id="machine-grid" class="machine-grid">'+machineCards(machines)+'</div>'}
function machineCards(list){return list.length?list.map(m=>'<article class="machine-card"><div class="machine-card-top"><span class="machine-symbol">▦</span>'+badge(m.state)+'</div><h3>'+esc(m.name)+'</h3><p>'+esc(m.area)+' · '+esc(m.line)+'</p><div class="card-foot"><span class="code">'+m.id+'</span><button class="btn small" data-machine="'+m.id+'">Abrir ficha →</button></div></article>').join(""):'<div class="panel empty-state">No hay equipos que coincidan.</div>'}
function machineDetail(id){const m=machines.find(x=>x.id===id);if(!m)return machinesPage();const docs=getDrafts().filter(d=>d.asset===m.id&&d.status==="approved");const params=new URLSearchParams({machine:m.id,name:m.name,location:m.area,faults:m.faults||"Sin averías típicas documentadas."});const url=location.origin+location.pathname+"?"+params.toString()+"#asset-"+m.id;const qr="https://api.qrserver.com/v1/create-qr-code/?size=220x220&margin=8&data="+encodeURIComponent(url);return head("ACTIVOS / FICHA",""+esc(m.name),"Ficha demostrativa del activo y acceso rápido desde planta.",'<button class="btn" data-go="machines">← Catálogo</button>')+'<div class="detail-layout"><div><div class="detail-banner"><span class="tag">'+m.id+'</span><h2>'+esc(m.name)+'</h2><p>'+esc(m.desc)+'</p></div><div class="panel"><div class="panel-head"><div><p>IDENTIFICACIÓN</p><h2>Datos del activo</h2></div>'+badge(m.state)+'</div><div class="detail-facts"><div class="fact"><small>Área</small><strong>'+m.area+'</strong></div><div class="fact"><small>Línea</small><strong>'+m.line+'</strong></div><div class="fact"><small>Responsable demo</small><strong>'+m.owner+'</strong></div></div></div><div class="panel" style="margin-top:13px"><div class="panel-head"><div><p>DOCUMENTACIÓN</p><h2>Biblioteca del equipo</h2></div><span class="tag amber">Demo · no validado</span></div><div class="detail-facts"><div class="fact"><small>Función del equipo</small><strong>'+esc(m.function)+'</strong></div><div class="fact"><small>Sistemas principales</small><strong>'+esc(m.systems)+'</strong></div><div class="fact"><small>Información a consultar</small><strong>'+esc(m.check)+'</strong></div></div><div class="procedure-list" style="margin-top:13px"><div class="procedure"><strong>01 · Ficha técnica y manuales</strong><p>Documentación del fabricante, versión, fecha de revisión y responsable de aprobación. En esta demo está pendiente de carga.</p></div><div class="procedure"><strong>02 · Conocimiento validado</strong><p>Notas y experiencias aportadas por expertos. Solo se muestra contenido aprobado por un perfil experto.</p>'+(docs.length?docs.map(d=>'<div class=\'approved-doc\'><strong>'+esc(d.title)+'</strong><p>'+esc(d.body)+'</p><small>'+esc(d.author)+' · Validado</small></div>').join(''):'<p>Todavía no hay fichas validadas para este equipo.</p>')+'</div><div class="procedure"><strong>Señales y averías típicas · demo</strong><p>'+esc(m.faults||"No se han documentado averías típicas para este activo.")+'</p></div><div class="procedure"><strong>Precauciones de seguridad</strong><p>No retirar resguardos ni intervenir sobre partes móviles o energizadas. Detener y escalar según el procedimiento oficial del centro. La consignación solo corresponde a personal autorizado y formado.</p></div><div class="procedure"><strong>03 · Historial de incidencias</strong><p>Registro cronológico de avisos, prioridad, estado y resolución autorizada.</p></div><div class="procedure"><strong>04 · Escalado seguro</strong><p>Contactos y procedimiento de notificación definidos por la organización. No se muestran instrucciones de reparación inventadas.</p></div></div><div class="safety-note">No hay procedimientos operativos reales cargados. La información debe aprobarse por personal autorizado antes de publicarse.</div></div></div><aside><div class="panel"><div class="panel-head"><div><p>ACCESO DESDE PLANTA</p><h2>QR del equipo</h2></div></div><div class="qr-box"><img src="'+qr+'" alt="QR de demostración '+m.id+'"><strong>'+m.id+'</strong><p>Escanea para abrir directamente esta ficha.</p><div class="qr-actions"><a class="btn primary small" href="'+qr+'" target="_blank" rel="noopener">Descargar QR ↓</a><button class="btn small" data-copy="'+esc(url)+'">Copiar enlace</button></div></div></div></aside></div>'}
function incidentsPage(){return head("OPERACIONES / SOPORTE","Registro de incidencias","Trazabilidad de avisos y estado de seguimiento.",'<button class="btn primary" data-action="new-incident">＋ Nuevo aviso</button>')+'<div class="panel"><div class="filter-row"><label class="searchbar" style="flex:1">⌕ <input id="incident-search" placeholder="Buscar referencia, equipo o descripción…"></label><select class="select" id="incident-state" style="max-width:180px"><option value="">Todos los estados</option><option>Abierta</option><option>En revisión</option><option>Resuelta</option></select></div><div class="table-wrap"><table><thead><tr><th>REFERENCIA</th><th>DESCRIPCIÓN</th><th>EQUIPO</th><th>FECHA</th><th>PRIORIDAD</th><th>ESTADO</th></tr></thead><tbody id="incident-rows">'+incidentRows(incidents)+'</tbody></table></div></div><div class="safety-note">Registros ficticios. En producción, los datos deben proceder de sistemas autorizados y contar con trazabilidad.</div>'}
function incidentRows(list){return list.length?list.map(i=>'<tr><td><strong>'+i.id+'</strong></td><td>'+esc(i.title)+'</td><td>'+i.machine+'</td><td>'+i.date+'</td><td>'+i.priority+'</td><td>'+badge(i.state)+'</td></tr>').join(""):'<tr><td colspan="6" class="empty-state">Sin resultados.</td></tr>'}
function academy(){return head("PERSONAS / DESARROLLO","Academia DammPulse","Microcontenidos para acelerar la acogida y reforzar conocimiento esencial.")+'<div class="learning-grid">'+lessons.map(l=>'<article class="lesson-card"><span class="tag">'+l.level+'</span><h3>'+l.title+'</h3><p>'+l.desc+'</p><div class="progress"><span style="width:'+(quizDone.has(l.id)?'100':'0')+'%"></span></div><div class="card-foot"><small class="help">'+l.time+' · Evaluación</small><button class="btn small primary" data-lesson="'+l.id+'">'+(quizDone.has(l.id)?'Repetir':'Comenzar')+' →</button></div></article>').join("")+'</div><div id="quiz-area"></div><div class="safety-note">Módulos de demostración. La formación operativa real debe ser aprobada por responsables competentes.</div>'}
function productsPage(){return head("BIBLIOTECA / PORTFOLIO","Universo cervecero Damm","Explora estilos, ingredientes, servicio y especificaciones publicadas. Los datos no disponibles se enlazan a la ficha oficial.",'<a class="btn primary" href="https://www.damm.com/es/cervezas" target="_blank" rel="noopener">Catálogo oficial ↗</a>')+'<div class="product-intro"><div><p class="eyebrow">PORTFOLIO · CERVEZAS</p><h2>Una familia. Muchos perfiles.</h2><p>Información de producto basada en fuentes públicas de Damm. Selecciona una referencia para consultar sus características.</p></div><div class="product-count"><strong>'+products.length+'</strong><span>referencias</span></div></div><div class="filter-row"><label class="searchbar" style="flex:1">⌕ <input id="product-search" placeholder="Buscar por nombre, estilo o característica…"></label></div><div class="machine-grid product-grid" id="product-grid">'+productCards(products)+'</div><p class="help" style="margin-top:18px">Las especificaciones marcadas como «Consultar ficha» no se han verificado y no se han completado por inferencia. Fuente oficial: Damm.</p>'}
function productCards(list){return list.map((p,i)=>'<article class="machine-card product-card"><div class="product-photo">'+(p[4]?'<img src="'+p[4]+'" alt="'+esc(p[0])+'" loading="lazy" onerror="this.style.display=\'none\'">':'<span class="photo-placeholder">'+esc(p[0].split(" ")[0])+'</span>')+'<span class="product-photo-label">DAMM · '+esc(p[2])+'</span></div><div class="product-content"><div class="product-meta"><span class="tag">'+esc(p[2])+'</span>'+(p[5]!=="Consultar ficha"?'<span class="tag gray">'+esc(p[5])+'</span>':'')+'</div><h3>'+esc(p[0])+'</h3><p>'+esc(p[1])+'</p><div class="card-foot"><span class="code">FICHA DE PRODUCTO</span><button class="btn small" data-product="'+i+'">Ver especificaciones →</button></div></div></article>').join("")}
function productDetail(i){const p=products[i];if(!p)return productsPage();return head("PORTFOLIO / FICHA DE PRODUCTO",esc(p[0]),esc(p[1]),'<button class="btn" data-go="products">← Volver al catálogo</button>')+'<div class="product-detail"><div class="product-detail-photo">'+(p[4]?'<img src="'+p[4]+'" alt="'+esc(p[0])+'">':'<div class="photo-placeholder">'+esc(p[0])+'</div>')+'</div><section><span class="tag">'+esc(p[2])+'</span><h2 style="font:800 30px Manrope;margin:15px 0 8px">'+esc(p[0])+'</h2><p style="color:var(--muted);line-height:1.8">'+esc(p[1])+'</p><div class="spec-grid"><div class="spec"><small>Graduación alcohólica</small><strong>'+esc(p[5])+'</strong></div><div class="spec"><small>Temperatura de servicio</small><strong>'+esc(p[6])+'</strong></div><div class="spec"><small>Amargor · IBU</small><strong>'+esc(p[7])+'</strong></div><div class="spec"><small>Color · EBC</small><strong>'+esc(p[8])+'</strong></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><div><p>COMPOSICIÓN</p><h2>Ingredientes</h2></div></div><p style="font-size:12px;line-height:1.8">'+esc(p[9])+'</p></div><div class="panel" style="margin-top:12px"><div class="panel-head"><div><p>EXPERIENCIA</p><h2>Nota de cata / perfil</h2></div></div><p style="font-size:12px;line-height:1.8">'+esc(p[10])+'</p></div><a class="btn primary" style="margin-top:15px" href="'+p[3]+'" target="_blank" rel="noopener">Consultar fuente oficial ↗</a></section></div>'}

function knowledgePage(){let drafts=getDrafts();return head("CAPTURA / VALIDACIÓN","Conocimiento experto","Convierte experiencia de las personas en borradores revisables y trazables.")+'<div class="grid-2 equal"><section class="panel"><div class="panel-head"><div><p>NUEVA CONTRIBUCIÓN</p><h2>Registrar conocimiento</h2></div><span class="tag amber">Borrador</span></div><form id="expert-form" class="form-grid"><div class="field"><label>Experto o equipo</label><input id="expert-author" required placeholder="Ej. Equipo de línea"></div><div class="field"><label>Activo relacionado</label><select id="expert-asset"><option value="">General</option>'+machines.map(m=>'<option>'+m.id+'</option>').join("")+'</select></div><div class="field full"><label>Título</label><input id="expert-title" required placeholder="Tema o aprendizaje compartido"></div><div class="field full"><label>Notas de conocimiento</label><textarea id="expert-body" required placeholder="Contexto, observaciones, señales y a quién escalar…"></textarea></div><div class="field full"><button class="btn primary" type="submit">Guardar borrador →</button><span class="help">En esta demo se guarda solo en este navegador. No se envía a Damm.</span></div></form></section><section class="panel"><div class="panel-head"><div><p>GOBIERNO DEL CONOCIMIENTO</p><h2>Flujo de publicación</h2></div></div><div class="procedure-list"><div class="procedure"><strong>01 · Captura</strong><p>El experto aporta audio, vídeo o texto por un canal autorizado.</p></div><div class="procedure"><strong>02 · Estructuración</strong><p>La IA transcribe y prepara un borrador con fuentes y contexto.</p></div><div class="procedure"><strong>03 · Revisión</strong><p>Un responsable valida precisión, seguridad, vigencia y permisos.</p></div><div class="procedure"><strong>04 · Publicación</strong><p>Solo las fichas aprobadas aparecen en búsquedas y QR de equipos.</p></div></div><div class="safety-note">La IA no debe aprobar ni publicar instrucciones industriales por sí sola.</div></section></div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><p>REPOSITORIO LOCAL</p><h2>Borradores registrados</h2></div><span class="tag amber">'+drafts.filter(d=>d.status!=="approved").length+' pendientes</span></div><div class="procedure-list">'+(drafts.length?drafts.map((d,i)=>'<div class="procedure"><div class="expert-row"><strong>'+esc(d.title)+'</strong>'+(d.status==="approved"?'<span class="tag">Validado</span>':'<button class="btn small primary" data-approve="'+i+'">Validar y publicar</button>')+'</div><p>'+esc(d.author)+' · '+esc(d.asset||"General")+' · '+(d.status==="approved"?"Visible en ficha QR":"Pendiente de revisión") +'</p><p>'+esc(d.body)+'</p></div>').join(""):'<div class="empty-state">Todavía no hay contribuciones.</div>')+'</div></section>'}
function getDrafts(){try{return JSON.parse(localStorage.getItem("dp-drafts")||"[]")}catch{return []}}
function assistant(){return head("ASISTENTE / CONSULTA","DAM Bot","Asistente demostrativo con respuestas guiadas por información pública y contenido de ejemplo.")+'<div class="chat-layout"><section class="chat-panel"><div class="chat-head"><div class="bot-avatar">✦</div><div><strong>DAM Bot · Asistente de conocimiento</strong><small><span class="pulse"></span> Demo local · sin conexión a sistemas internos</small></div></div><div class="chat-messages" id="chat-messages"><div class="message bot">¡Hola! Soy DAM Bot. 👋<br><br>Puedo ayudarte a explorar el catálogo público de cervezas, orientarte por DammPulse o explicar cómo funciona el flujo de conocimiento experto. ¿Qué te gustaría saber?<small>Asistente de demostración · No es un sistema oficial de Damm</small></div></div><form class="chat-input" id="chat-form"><input id="chat-question" placeholder="Escribe aquí tu pregunta…" autocomplete="off" required><button class="btn primary" type="submit">Enviar ↑</button></form></section><aside class="chat-side"><h3>Preguntas sugeridas</h3><button class="suggestion" data-prompt="Hola, ¿qué puedes hacer?">👋 ¿Qué puedes hacer?</button><button class="suggestion" data-prompt="¿Qué es Voll-Damm?">¿Qué es Voll-Damm?</button><button class="suggestion" data-prompt="¿Qué cervezas sin alcohol tiene Damm?">Cervezas sin alcohol</button><button class="suggestion" data-prompt="¿Cómo funciona el QR de las máquinas?">¿Cómo funciona el QR?</button><button class="suggestion" data-prompt="¿Cómo se valida el conocimiento experto?">Validación experta</button><div class="chat-warning">⚠ No tengo acceso a datos internos ni procedimientos de fábrica. No inventaré instrucciones operativas. Para información oficial, consulta Damm.</div></aside></div>'}
function answer(q){const s=norm(q);if(/^(hola|buenas|hey|buenos dias|buenas tardes|buenas noches|que tal|holi)/.test(s)||s.includes("como estas"))return "¡Hola! 😊 Encantado de ayudarte. Puedo explicarte el proyecto DammPulse, consultar información pública del catálogo de cervezas o enseñarte cómo se organiza el conocimiento de máquinas. ¿Por dónde empezamos?";
if(s.includes("quien eres")||s.includes("que puedes hacer")||s.includes("ayuda"))return "Soy DAM Bot, el asistente de demostración de DammPulse. Puedo responder preguntas sobre los productos públicos incluidos en esta demo, explicar el uso de los módulos y orientar sobre captura y validación del conocimiento. No estoy conectado a sistemas internos de Damm.";
const p=products.find(x=>s.includes(norm(x[0])));if(p)return p[0]+": "+p[1]+". Estilo: "+p[2]+". Graduación: "+p[5]+". Servicio: "+p[6]+". Ingredientes: "+p[9]+". "+p[10]+" Fuente oficial: "+p[3];
if(s.includes("sin alcohol")||s.includes("0 0")||s.includes("0,0"))return "En el portfolio público de Damm aparecen Free Damm, Free Damm Limón, Free Damm Tostada y Daura Non-Alc. Puedo mostrarte las fichas disponibles en Producto Damm. Para ingredientes y datos actualizados, consulta las fichas oficiales.";
if(s.includes("cerveza")||s.includes("catalogo")||s.includes("productos"))return "El catálogo público incluye, entre otras, Estrella Damm, Bohemia, Voll-Damm, Damm Lemon, Complot, Inedit, Free Damm, Bock Damm, Daura, A.K. Damm y Xibeca. Puedes ver el catálogo oficial desde la sección «Producto Damm».";
if(s.includes("qr"))return "Cada QR identifica un activo y abre su ficha contextual: identificación, documentación aprobada, historial y contactos. En esta demo los equipos son ficticios; en una implantación real, cada QR debería apuntar a una ficha autorizada.";
if(s.includes("averia")||s.includes("incidencia")||s.includes("fallo"))return "DammPulse propone registrar el código del equipo, fecha y hora, síntoma observable y contexto. Después se escala por el canal oficial. Esta demo no proporciona diagnósticos ni pasos de reparación.";
if(s.includes("experto")||s.includes("valid")||s.includes("conocimiento"))return "El flujo propuesto tiene cuatro fases: captura de experiencia, estructuración asistida por IA, revisión por un responsable autorizado y publicación de la ficha aprobada. La IA nunca valida por sí sola.";
if(s.includes("formacion")||s.includes("academia")||s.includes("aprender"))return "La Academia reúne cápsulas breves y evaluaciones. La idea es adaptar el aprendizaje al puesto y a los equipos que utiliza cada persona.";
if(s.includes("maquina")||s.includes("equipo")||s.includes("activo"))return "En «Equipos y QR» puedes buscar activos de demostración y abrir sus fichas. Los códigos y equipos actuales son ficticios, preparados para enseñar cómo funcionaría el sistema.";
if(s.includes("damm"))return "DammPulse es una propuesta académica independiente para mejorar la transferencia de conocimiento industrial. No es una aplicación oficial ni está conectada a los sistemas internos de Damm.";
return "Buena pregunta. No tengo información suficiente y prefiero no inventar una respuesta. Puedo ayudarte con el catálogo público, los módulos de DammPulse o el flujo de conocimiento experto. Si es una cuestión de fábrica, debe responderla un responsable autorizado."}
function addChat(text,type){const box=$("#chat-messages");const el=document.createElement("div");el.className="message "+type;el.textContent=text;if(type==="bot"){const sm=document.createElement("small");sm.textContent="Respuesta demo · Comprueba siempre la fuente oficial";el.appendChild(sm)}box.appendChild(el);box.scrollTop=box.scrollHeight}
function currentUser(){try{return JSON.parse(localStorage.getItem("dp-session")||"null")}catch{return null}}
function getUsers(){try{return JSON.parse(localStorage.getItem("dp-users")||"[]")}catch{return []}}
function saveUsers(users){localStorage.setItem("dp-users",JSON.stringify(users))}
function renderAuth(mode="login",message=""){
 const root=$("#auth-root");document.querySelector(".app-shell").hidden=true;root.hidden=false;
 root.innerHTML='<div class="auth-backdrop"><section class="auth-card"><div class="auth-brand"><span class="auth-mark">D</span><div><strong>DAMMPULSE 360</strong><small>INDUSTRIAL KNOWLEDGE PLATFORM</small></div></div><p class="auth-kicker">TU ESPACIO DE TRABAJO</p><h1>'+(mode==="register"?"Crea tu cuenta.":"Bienvenido de nuevo.")+'</h1><p class="auth-intro">Accede a tu espacio personal de DammPulse.</p><div class="auth-tabs"><button data-auth-view="login" class="'+(mode==="login"?"active":"")+'">Iniciar sesión</button><button data-auth-view="register" class="'+(mode==="register"?"active":"")+'">Crear cuenta</button></div>'+(message?'<div class="auth-message">'+esc(message)+'</div>':'')+
 (mode==="login"?'<form id="login-form" class="auth-form"><label>Usuario<input name="username" autocomplete="username" placeholder="tu.usuario" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required></label><button class="btn auth-submit">Entrar en DammPulse →</button></form>':'<form id="register-form" class="auth-form"><label>Nombre visible<input name="name" maxlength="40" required></label><label>Usuario<input name="username" minlength="3" maxlength="20" pattern="[A-Za-z0-9._-]{3,20}" required><small>Tu ID será usuario@dammpulse.local. No necesitas Gmail.</small></label><label>Contraseña<input name="password" type="password" minlength="8" required></label><label>Repite la contraseña<input name="confirm" type="password" minlength="8" required></label><button class="btn auth-submit">Crear mi cuenta →</button></form>')+
 '<p class="auth-demo-note">Demo local: las cuentas se guardan solo en este navegador. No uses contraseñas personales ni datos reales.</p><div class="auth-foot">Proyecto académico independiente · Creado por Tarik</div></section><aside class="auth-side"><div class="auth-side-orbit">360°</div><h2>EL CONOCIMIENTO<br><em>EN MOVIMIENTO.</em></h2><small>EQUIPOS · PERSONAS · MEJORA CONTINUA</small></aside></div>';
}
async function passwordDigest(password,salt){
 const source=salt+":"+password;
 if(globalThis.crypto?.subtle&&globalThis.TextEncoder){
  const hash=await globalThis.crypto.subtle.digest("SHA-256",new TextEncoder().encode(source));
  return Array.from(new Uint8Array(hash)).map(x=>x.toString(16).padStart(2,"0")).join("");
 }
 // Compatibilidad para navegadores antiguos: solo cuentas ficticias de esta demo.
 let h1=0x811c9dc5,h2=0x9e3779b9;
 for(let n=0;n<source.length;n++){const x=source.charCodeAt(n);h1=Math.imul(h1^x,0x01000193);h2=Math.imul(h2^x,0x85ebca6b)}
 return "demo-"+(h1>>>0).toString(16)+(h2>>>0).toString(16);
}
function enterSession(user){localStorage.setItem("dp-session",JSON.stringify(user));$("#auth-root").hidden=true;document.querySelector(".app-shell").hidden=false;render()}
function adminPage(){const users=getUsers();return '<section class="admin-hero"><div><p class="eyebrow">CONTROL CENTER / ADMIN</p><h1>Panel de administración.</h1><p>Directorio de cuentas de la demo.</p></div><div class="admin-lock">⌘</div></section><div class="stat-grid"><article class="stat-card"><span class="stat-label">Cuentas registradas</span><strong>'+users.length+'</strong><small>En este navegador</small></article><article class="stat-card"><span class="stat-label">Administrador</span><strong>TARIK</strong><small>Acceso de demostración</small></article></div><section class="panel admin-users"><div class="panel-head"><div><p>DIRECTORIO</p><h2>Usuarios registrados</h2></div></div>'+(users.length?'<div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Identificador</th><th>Alta</th></tr></thead><tbody>'+users.map(u=>'<tr><td>'+esc(u.name)+'</td><td>'+esc(u.email)+'</td><td>'+esc(u.createdAt)+'</td></tr>').join("")+'</tbody></table></div>':'<p class="admin-empty">Todavía no hay usuarios registrados en este navegador.</p>')+'</section><div class="safety-note">Demo local: la clave admin está en el código público y no ofrece seguridad real. Cuentas no sincronizadas entre móviles.</div>'}
function render(){
  try {
    const user=currentUser();
    if(!user){renderAuth();return}
    $("#auth-root").hidden=true;document.querySelector(".app-shell").hidden=false;
    $("#profile-name").textContent=user.name||"Usuario";$("#profile-role").textContent=user.role==="admin"?"Administrador · Demo":"Cuenta demo";
    $("#profile-avatar").textContent=String(user.name||"U").split(/\s+/).map(x=>x[0]).join("").slice(0,2).toUpperCase();$("#top-avatar").textContent=$("#profile-avatar").textContent;
    document.querySelector(".admin-nav").hidden=user.role!=="admin";
    let h; try { h=decodeURIComponent(location.hash.slice(1)||"home"); } catch { h="home"; }
    const asset=h.startsWith("asset-"),id=asset?"asset":h;
    const map={home:"Inicio",machines:"Equipos",incidents:"Incidencias",academy:"Academia",knowledge:"Conocimiento experto",products:"Producto Damm",assistant:"DAM Bot",admin:"Administración"};
    $("#current-section").textContent=map[id]||"Inicio";
    document.querySelectorAll(".nav-link").forEach(a=>a.classList.toggle("active",a.dataset.view===id));
    $("#sidebar").classList.remove("open");
    const pages={home,machines:machinesPage,qr:qrPage,incidents:incidentsPage,academy,knowledge:knowledgePage,products:productsPage,admin:adminPage};
    view.innerHTML=h==="admin"&&user.role!=="admin"?home():asset?machineDetail(h.slice(6)):id==="assistant"?assistant():id.startsWith("product-")?productDetail(Number(id.slice(8))):(pages[h]||home)();
    view.focus({preventScroll:true});
  } catch(error) {
    console.error("DammPulse render error:",error);
    view.innerHTML='<section class="panel app-error"><p class="eyebrow">RECUPERACIÓN DE LA APLICACIÓN</p><h2>Esta sección no se ha podido cargar</h2><p>Vuelve al inicio o reintenta. La aplicación no se quedará en blanco.</p><div class="error-actions"><button class="btn primary" onclick="location.hash=\'home\'">Ir al inicio</button><button class="btn" onclick="location.reload()">Reintentar</button></div></section>';
  }
}
document.addEventListener("click",e=>{
 const tab=e.target.closest("[data-auth-view]");if(tab){renderAuth(tab.dataset.authView);return}
 if(e.target.closest("[data-logout]")){localStorage.removeItem("dp-session");location.hash="home";renderAuth("login","Sesión cerrada.")}
});
document.addEventListener("submit",async e=>{
 if(e.target.id==="login-form"){e.preventDefault();const f=new FormData(e.target),u=String(f.get("username")).trim().toLowerCase(),p=String(f.get("password"));
 if(u==="tarik"&&p==="Tarik 123"){enterSession({name:"Tarik",username:"tarik",email:"tarik@dammpulse.local",role:"admin",demo:true});return}
 const a=getUsers().find(x=>x.username===u||x.email===u);if(!a){renderAuth("login","Usuario o contraseña incorrectos.");return}
 try{if(await passwordDigest(p,a.salt)!==a.passwordHash){renderAuth("login","Usuario o contraseña incorrectos.");return}enterSession({name:a.name,username:a.username,email:a.email,role:"user",demo:true})}catch{renderAuth("login","No se pudo verificar la cuenta.")}}
 if(e.target.id==="register-form"){e.preventDefault();const f=new FormData(e.target),name=String(f.get("name")).trim(),username=String(f.get("username")).trim().toLowerCase(),password=String(f.get("password")),confirm=String(f.get("confirm"));
 if(password.length<8){renderAuth("register","Usa al menos 8 caracteres.");return}if(password!==confirm){renderAuth("register","Las contraseñas no coinciden.");return}
 if(!/^[a-z0-9._-]{3,20}$/.test(username)||username==="tarik"){renderAuth("register","Usuario no válido o reservado.");return}
 const users=getUsers();if(users.some(x=>x.username===username)){renderAuth("register","Ese usuario ya existe.");return}
 try{const randomBytes=new Uint8Array(16);if(globalThis.crypto?.getRandomValues)globalThis.crypto.getRandomValues(randomBytes);else for(let n=0;n<randomBytes.length;n++)randomBytes[n]=Math.floor(Math.random()*256);const salt=Array.from(randomBytes).map(x=>x.toString(16).padStart(2,"0")).join(""),passwordHash=await passwordDigest(password,salt),a={name,username,email:username+"@dammpulse.local",salt,passwordHash,createdAt:new Date().toLocaleDateString("es-ES")};users.push(a);saveUsers(users);enterSession({name,username,email:a.email,role:"user",demo:true})}catch(error){console.error("DammPulse registration:",error);renderAuth("register","No se pudo guardar la cuenta. Comprueba el almacenamiento del navegador e inténtalo de nuevo.")}}
});
document.addEventListener("click",e=>{const g=e.target.closest("[data-go]");if(g){go(g.dataset.go);return}const ap=e.target.closest("[data-approve]");if(ap){const ds=getDrafts(),d=ds[Number(ap.dataset.approve)];if(d){d.status="approved";d.approvedAt=new Date().toISOString();localStorage.setItem("dp-drafts",JSON.stringify(ds));toast("Ficha validada y publicada en el QR del equipo");render()}return}const pd=e.target.closest("[data-product]");if(pd){go("product-"+pd.dataset.product);return}const m=e.target.closest("[data-machine]");if(m){go("asset-"+m.dataset.machine);return}const p=e.target.closest("[data-prompt]");if(p){const input=$("#chat-question");input.value=p.dataset.prompt;$("#chat-form").requestSubmit();return}const l=e.target.closest("[data-lesson]");if(l){showQuiz(l.dataset.lesson);return}const c=e.target.closest("[data-copy]");if(c){navigator.clipboard?.writeText(c.dataset.copy).then(()=>toast("Enlace copiado")).catch(()=>toast("No se pudo copiar"));return}if(e.target.closest('[data-action="new-incident"]'))openIncident();});
window.addEventListener("hashchange",render);
$("#menu-toggle").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));
document.addEventListener("input",e=>{if(e.target.id==="machine-search"||e.target.id==="area-filter"){const q=norm($("#machine-search").value),a=$("#area-filter").value;$("#machine-grid").innerHTML=machineCards(machines.filter(m=>norm(m.name+" "+m.id+" "+m.area).includes(q)&&(!a||m.area===a)))}if(e.target.id==="product-search")$("#product-grid").innerHTML=productCards(products.filter(p=>norm(p.join(" ")).includes(norm(e.target.value))));if(e.target.id==="incident-search"||e.target.id==="incident-state"){const q=norm($("#incident-search").value),s=$("#incident-state").value;$("#incident-rows").innerHTML=incidentRows(incidents.filter(i=>norm(Object.values(i).join(" ")).includes(q)&&(!s||i.state===s)))}});
document.addEventListener("submit",e=>{if(e.target.id==="chat-form"){e.preventDefault();const q=$("#chat-question").value.trim();if(!q)return;addChat(q,"user");$("#chat-question").value="";setTimeout(()=>addChat(answer(q),"bot"),120)}if(e.target.id==="expert-form"){e.preventDefault();const d=getDrafts();d.unshift({author:$("#expert-author").value,asset:$("#expert-asset").value,title:$("#expert-title").value,body:$("#expert-body").value,date:new Date().toLocaleDateString("es-ES"),status:"pending"});localStorage.setItem("dp-drafts",JSON.stringify(d));toast("Borrador guardado en este navegador");render()}if(e.target.id==="incident-form"){e.preventDefault();incidents.unshift({id:"INC-DEMO-"+(incidents.length+1),title:$("#new-title").value,machine:$("#new-machine").value,date:new Date().toLocaleDateString("es-ES"),priority:$("#new-priority").value,state:"Abierta",desc:$("#new-desc").value});modal.innerHTML="";toast("Aviso demo registrado");render() }});
function showQuiz(id){const l=lessons.find(x=>x.id===id),a=$("#quiz-area");a.innerHTML='<section class="panel quiz"><div class="panel-head"><div><p>'+l.id+' · '+l.level+'</p><h2>'+l.title+'</h2></div><button class="btn small" id="quiz-close">Cerrar</button></div><h3>'+l.q+'</h3>'+l.a.map((x,i)=>'<button class="answer" data-answer="'+i+'">'+x+'</button>').join("")+'<p id="quiz-feedback" class="help"></p></section>';a.scrollIntoView({behavior:"smooth"});$("#quiz-close").onclick=()=>a.innerHTML="";a.querySelectorAll("[data-answer]").forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.answer)===l.correct;a.querySelectorAll(".answer").forEach((x,i)=>{x.disabled=true;if(i===l.correct)x.classList.add("correct")});if(!ok)b.classList.add("wrong");$("#quiz-feedback").textContent=(ok?"¡Correcto! ":"No es correcto. ")+l.why;quizDone.add(l.id)})}
function openIncident(){modal.innerHTML='<div class="modal-backdrop"><section class="modal"><div class="modal-head"><h2>Nuevo aviso de demostración</h2><button class="close" id="modal-close">×</button></div><form id="incident-form" class="form-grid"><div class="field full"><label>Título del aviso</label><input id="new-title" required></div><div class="field"><label>Equipo</label><select id="new-machine">'+machines.map(m=>'<option>'+m.id+'</option>').join("")+'</select></div><div class="field"><label>Prioridad</label><select id="new-priority"><option>Baja</option><option selected>Media</option><option>Alta</option></select></div><div class="field full"><label>Hechos observados</label><textarea id="new-desc" required></textarea></div><div class="field full"><button class="btn primary">Guardar aviso demo</button><span class="help">Solo se añade a esta sesión. No se envía a sistemas reales.</span></div></form></section></div>';$("#modal-close").onclick=()=>modal.innerHTML=""}

function home(){return '<section class="hero"><div class="hero-copy"><p class="eyebrow">DAMMPULSE 360 · INDUSTRIAL INTELLIGENCE</p><h1>La excelencia<br>empieza en <em>planta.</em></h1><p>Conocimiento experto, activos conectados y aprendizaje operativo en una experiencia digital diseñada para el ritmo de la industria.</p><div class="hero-actions"><button class="btn gold" data-go="machines">Explorar equipos ↗</button><button class="btn glass" data-go="qr">＋ Generar QR</button></div><div class="hero-proof"><span>● ENTORNO DE DEMOSTRACIÓN</span><span>CONOCIMIENTO · EQUIPOS · PERSONAS</span></div></div><div class="hero-side"><div class="hero-orbit">360°</div><div class="hero-side-label"><strong>PLANTA CONECTADA</strong><small>Conocimiento validado para cada activo</small></div></div></section>'+shellStats()+'<div class="section-heading"><div><p class="eyebrow">CENTRO DE OPERACIONES</p><h2>Todo conectado. Todo más claro.</h2></div></div><section class="quick-grid"><a class="quick-card" href="#machines"><span class="q-icon">▦</span><strong>Equipos y QR</strong><small>Consulta la ficha de cada activo</small><b>Explorar activos ↗</b></a><a class="quick-card" href="#qr"><span class="q-icon">⌗</span><strong>Generador QR</strong><small>Crea etiquetas digitales por máquina</small><b>Crear un QR ↗</b></a><a class="quick-card" href="#incidents"><span class="q-icon">◉</span><strong>Incidencias</strong><small>Seguimiento de avisos de ejemplo</small></a><a class="quick-card" href="#knowledge"><span class="q-icon">✳</span><strong>Conocimiento experto</strong><small>Captura, revisión y publicación</small></a></section><section class="photo-strip"><div class="photo-strip-copy"><p class="eyebrow">EL CORAZÓN DE LA PRODUCCIÓN</p><h2>Precisión en cada proceso.</h2><p>De fermentación a envasado: información contextual para cada activo.</p><button class="btn gold" data-go="machines">Ver activos conectados →</button></div><div class="photo-strip-image"></div></section><section class="beer-world"><div class="beer-world-heading"><div><p class="eyebrow">EL UNIVERSO CERVECERO</p><h2>Una cultura que se disfruta en cada detalle.</h2><p>Tradición, ingredientes y tecnología: el viaje detrás de cada cerveza.</p></div><span class="beer-stamp">DESDE<br><b>1876</b></span></div><div class="beer-gallery"><article class="beer-tile beer-tile-main"><img src="https://images.unsplash.com/photo-1535958636474-b021ee887b13?auto=format&fit=crop&w=1200&q=85" alt="Vaso de cerveza dorada con espuma" loading="lazy"><div class="beer-tile-caption"><span>01 · EL MOMENTO</span><h3>El arte de servir.</h3></div></article><article class="beer-tile"><img src="https://images.unsplash.com/photo-1608270586620-248524c67de9?auto=format&fit=crop&w=900&q=85" alt="Cervezas en vasos" loading="lazy"><div class="beer-tile-caption"><span>02 · LOS MATICES</span><h3>Color, aroma y carácter.</h3></div></article><article class="beer-tile"><img src="https://images.unsplash.com/photo-1513558161293-cdaf765edfd4?auto=format&fit=crop&w=900&q=85" alt="Ingredientes frescos" loading="lazy"><div class="beer-tile-caption"><span>03 · EL ORIGEN</span><h3>Ingredientes con historia.</h3></div></article></div></section><section class="brew-journey"><div class="brew-journey-title"><p class="eyebrow">DEL ORIGEN AL BRINDIS</p><h2>Un viaje en cuatro momentos.</h2></div><div class="brew-steps"><article><span>01</span><b>Ingredientes</b><small>Malta, lúpulo, agua y levadura.</small></article><article><span>02</span><b>Elaboración</b><small>La precisión transforma cada ingrediente.</small></article><article><span>03</span><b>Envasado</b><small>Tecnología y cuidado en cada línea.</small></article><article><span>04</span><b>Disfrute</b><small>El resultado llega al vaso.</small></article></div></section><section class="grid-2"><article class="panel"><div class="panel-head"><div><p>ACTIVOS · DEMO</p><h2>Equipos destacados</h2></div><button class="text-link" data-go="machines">Ver todos →</button></div><div class="machine-list">'+machines.slice(0,3).map(m=>'<div class="machine-row"><div class="row-main"><strong>'+esc(m.name)+'</strong><small>'+m.id+' · '+esc(m.area)+'</small></div>'+badge(m.state)+'</div>').join("")+'</div></article><article class="panel"><div class="panel-head"><div><p>ACTIVIDAD · DEMO</p><h2>Últimos avisos</h2></div><button class="text-link" data-go="incidents">Ver registro →</button></div><div class="incident-list">'+incidents.map(i=>'<div class="incident-row"><div class="row-main"><strong>'+esc(i.title)+'</strong><small>'+i.id+' · '+i.machine+'</small></div>'+badge(i.state)+'</div>').join("")+'</div></article></section><div class="safety-note">Entorno académico. Activos e incidencias ficticios. No utilizar esta demo para operar equipos reales.</div>'}
function machinesPage(){return '<section class="machines-banner"><div><p class="eyebrow">ASSET INTELLIGENCE / 02</p><h1>Equipos bajo control.</h1><p>Una ficha digital para cada activo. Escanea, consulta y escala con contexto.</p></div><div class="machines-banner-stat"><strong>'+String(machines.length).padStart(2,"0")+'</strong><span>ACTIVOS DEMO</span></div></section>'+head("GESTIÓN DE ACTIVOS","Catálogo de equipos","Busca por nombre, código o área y abre su ficha contextual.",'<button class="btn primary" data-go="qr">＋ Generar QR</button>')+'<div class="filter-row"><label class="searchbar" style="flex:1">⌕ <input id="machine-search" placeholder="Buscar equipo, código o área…"></label><select class="select" id="area-filter" style="max-width:190px"><option value="">Todas las áreas</option>'+[...new Set(machines.map(m=>m.area))].map(x=>'<option>'+x+'</option>').join("")+'</select></div><div id="machine-grid" class="machine-grid">'+machineCards(machines)+'</div>'}
function machineCards(list){const photos=["https://www.krones.com/media/images/202507JP01_0053_1240x826px.jpg","https://www.krones.com/media/images/202007BO01_0048_korr_1880px.jpg","https://static.downtheroadbrewery.com/cloud/miBpoKpqRllSkopnillnl/commercial-brewery-building-requirements-industrial-brewery-facility.jpg"];return list.length?list.map((m,i)=>'<article class="machine-card"><div class="machine-card-photo"><img src="'+photos[i%photos.length]+'" alt="Instalación industrial de cervecería" loading="lazy"><span class="machine-photo-shade"></span><span class="machine-photo-id">'+m.id+'</span>'+badge(m.state)+'</div><div class="machine-card-body"><p class="machine-area">'+esc(m.area)+' · '+esc(m.line)+'</p><h3>'+esc(m.name)+'</h3><p class="machine-description">'+esc(m.desc)+'</p><div class="card-foot"><span class="code">'+m.docs+' DOCS · FICHA DEMO</span><button class="btn small" data-machine="'+m.id+'">Abrir ficha →</button></div></div></article>').join(""):'<div class="panel empty-state">No hay equipos que coincidan.</div>'}
function qrPage(){return head("CONECTIVIDAD / ACTIVOS","Generador de QR","Crea una etiqueta digital para identificar una máquina y abrir su ficha desde el móvil.")+'<div class="qr-workspace"><section class="panel qr-form-panel"><div class="panel-head"><div><p>CONFIGURACIÓN DEL ACTIVO</p><h2>Datos de la máquina</h2></div><span class="tag amber">DEMO</span></div><form id="qr-generator-form" class="form-grid"><div class="field full"><label>Nombre de la máquina</label><input id="qr-name" required maxlength="70" placeholder="Ej. Llenadora de línea 02"></div><div class="field"><label>Ubicación / área</label><input id="qr-location" required maxlength="60" placeholder="Ej. Envasado · Línea 2"></div><div class="field"><label>Código del activo (opcional)</label><input id="qr-code" maxlength="18" placeholder="Se genera automáticamente"></div><div class="field full"><label>Averías típicas o señales observadas</label><textarea id="qr-faults" rows="4" maxlength="500" placeholder="Describe síntomas conocidos, sin incluir instrucciones de reparación no validadas…"></textarea><small class="help">Se mostrará como referencia en la ficha. No sustituye procedimientos aprobados.</small></div><div class="field full"><button class="btn primary" type="submit">Generar código QR ↗</button></div></form></section><aside class="panel qr-preview-panel"><div class="panel-head"><div><p>VISTA PREVIA</p><h2>Etiqueta inteligente</h2></div><span class="live-dot">LISTO PARA GENERAR</span></div><div id="qr-preview" class="qr-preview"><div class="qr-placeholder"><span>⌗</span><strong>Tu QR aparecerá aquí</strong><small>Completa los datos de la máquina</small></div></div><div id="qr-result-actions" class="qr-result-actions" hidden><button class="btn gold" id="qr-download">Descargar PNG ↓</button><button class="btn" id="qr-print">Imprimir etiqueta</button></div><p class="help">El QR abre la ficha del activo en DammPulse. Los datos esenciales viajan en el enlace para abrirse desde otro móvil.</p></aside></div><div class="safety-note">Datos de demostración. No incluyas información confidencial ni procedimientos reales sin autorización.</div>'}
document.addEventListener("submit",e=>{if(e.target.id!=="qr-generator-form")return;e.preventDefault();const name=$("#qr-name").value.trim(),area=$("#qr-location").value.trim(),faults=$("#qr-faults").value.trim(),raw=$("#qr-code").value.trim().toUpperCase(),id=raw||("QR-"+Date.now().toString().slice(-7));if(machines.some(m=>m.id===id)){toast("Ese código ya existe. Introduce otro.");return}const m={id,name,area,line:"Activo QR",state:"Demo",owner:"Pendiente",docs:0,desc:"Ficha creada mediante el generador QR. Verificar con el responsable del activo.",function:"Pendiente de documentación aprobada.",systems:"Pendiente de confirmar.",check:"Consultar documentación oficial y responsable autorizado.",faults:faults||"Sin averías típicas documentadas."};machines.push(m);const saved=JSON.parse(localStorage.getItem("dp-custom-machines")||"[]");saved.push(m);localStorage.setItem("dp-custom-machines",JSON.stringify(saved));const params=new URLSearchParams({machine:id,name,location:area,faults:m.faults});const target=location.origin+location.pathname+"?"+params.toString()+"#asset-"+id;const image="https://api.qrserver.com/v1/create-qr-code/?size=420x420&margin=14&data="+encodeURIComponent(target);$("#qr-preview").innerHTML='<div class="qr-label"><div class="qr-label-top"><span>DAMMPULSE 360</span><span>ASSET ID / '+esc(id)+'</span></div><img id="generated-qr-image" src="'+image+'" alt="Código QR para '+esc(name)+'"><h3>'+esc(name)+'</h3><p>'+esc(area)+'</p><small>ESCANEA PARA ABRIR LA FICHA TÉCNICA</small></div>';$("#qr-result-actions").hidden=false;$("#qr-download").onclick=async()=>{try{const res=await fetch(image);const blob=await res.blob();const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="DammPulse-QR-"+id+".png";a.click();URL.revokeObjectURL(a.href)}catch(err){window.open(image,"_blank","noopener")}};$("#qr-print").onclick=()=>{const w=window.open("","_blank");if(!w){toast("Permite las ventanas emergentes para imprimir");return}w.document.write('<html><head><title>Etiqueta '+esc(id)+'</title><style>body{font-family:Arial;text-align:center;padding:28px;color:#16362c}.label{border:2px solid #16362c;border-radius:16px;padding:22px;max-width:340px;margin:auto}.label img{width:260px;height:260px}</style></head><body><div class="label"><strong>DAMMPULSE 360 · '+esc(id)+'</strong><br><img src="'+image+'"><h2>'+esc(name)+'</h2><p>'+esc(area)+'</p><small>ESCANEA PARA ABRIR LA FICHA</small></div></body></html>');w.document.close();w.onload=()=>w.print()};toast("QR generado correctamente")});

if(currentUser())render();else renderAuth();
let deferredInstallPrompt=null;
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();deferredInstallPrompt=e;const b=$("#install-app");if(b)b.hidden=false});
const installButton=$("#install-app");if(installButton){installButton.hidden=false;installButton.addEventListener("click",async()=>{if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;return}const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);toast(ios?"En Safari: Compartir → Añadir a pantalla de inicio.":"En Chrome: menú ⋮ → Instalar aplicación o Añadir a pantalla de inicio.");});}
if("serviceWorker"in navigator&&location.protocol.startsWith("http"))window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}));

