function machinesPage(){return '<section class="machines-banner"><div><p class="eyebrow">ASSET INTELLIGENCE / 02</p><h1>Equipos bajo control.</h1><p>Una ficha digital para cada activo. Escanea, consulta y escala con contexto.</p></div><div class="machines-banner-stat"><strong>'+String(machines.length).padStart(2,"0")+'</strong><span>ACTIVOS DEMO</span></div></section>'+head("GESTIÓN DE ACTIVOS","Catálogo de equipos","Busca por nombre, código o área y abre su ficha contextual.",'<button class="btn primary" data-go="qr">＋ Generar QR</button>')+'<div class="filter-row"><label class="searchbar" style="flex:1">⌕ <input id="machine-search" placeholder="Buscar equipo, código o área…"></label><select class="select" id="area-filter" style="max-width:190px"><option value="">Todas las áreas</option>'+[...new Set(machines.map(m=>m.area))].map(x=>'<option>'+x+'</option>').join("")+'</select></div><div id="machine-grid" class="machine-grid">'+machineCards(machines)+'</div>'}
function machineCards(list){const photos=["https://www.krones.com/media/images/202507JP01_0053_1240x826px.jpg","https://www.krones.com/media/images/202007BO01_0048_korr_1880px.jpg","https://static.downtheroadbrewery.com/cloud/miBpoKpqRllSkopnillnl/commercial-brewery-building-requirements-industrial-brewery-facility.jpg"];return list.length?list.map((m,i)=>'<article class="machine-card"><div class="machine-card-photo"><img src="'+photos[i%photos.length]+'" alt="Instalación industrial de cervecería" loading="lazy"><span class="machine-photo-shade"></span><span class="machine-photo-id">'+m.id+'</span>'+badge(m.state)+'</div><div class="machine-card-body"><p class="machine-area">'+esc(m.area)+' · '+esc(m.line)+'</p><h3>'+esc(m.name)+'</h3><p class="machine-description">'+esc(m.desc)+'</p><div class="card-foot"><span class="code">'+m.docs+' DOCS · FICHA DEMO</span><button class="btn small" data-machine="'+m.id+'">Abrir ficha →</button></div></div></article>').join(""):'<div class="panel empty-state">No hay equipos que coincidan.</div>'}
function qrPage(){return head("CONECTIVIDAD / ACTIVOS","Generador de QR","Crea una etiqueta digital para identificar una máquina y abrir su ficha desde el móvil.")+'<div class="qr-workspace"><section class="panel qr-form-panel"><div class="panel-head"><div><p>CONFIGURACIÓN DEL ACTIVO</p><h2>Datos de la máquina</h2></div><span class="tag amber">DEMO</span></div><form id="qr-generator-form" class="form-grid"><div class="field full"><label>Nombre de la máquina</label><input id="qr-name" required maxlength="70" placeholder="Ej. Llenadora de línea 02"></div><div class="field"><label>Ubicación / área</label><input id="qr-location" required maxlength="60" placeholder="Ej. Envasado · Línea 2"></div><div class="field"><label>Código del activo (opcional)</label><input id="qr-code" maxlength="18" placeholder="Se genera automáticamente"></div><div class="field full"><label>Averías típicas o señales observadas</label><textarea id="qr-faults" rows="4" maxlength="500" placeholder="Describe síntomas conocidos, sin incluir instrucciones de reparación no validadas…"></textarea><small class="help">Se mostrará como referencia en la ficha. No sustituye procedimientos aprobados.</small></div><div class="field full"><button class="btn primary" type="submit">Generar código QR ↗</button></div></form></section><aside class="panel qr-preview-panel"><div class="panel-head"><div><p>VISTA PREVIA</p><h2>Etiqueta inteligente</h2></div><span class="live-dot">LISTO PARA GENERAR</span></div><div id="qr-preview" class="qr-preview"><div class="qr-placeholder"><span>⌗</span><strong>Tu QR aparecerá aquí</strong><small>Completa los datos de la máquina</small></div></div><div id="qr-result-actions" class="qr-result-actions" hidden><button class="btn gold" id="qr-download">Descargar PNG ↓</button><button class="btn" id="qr-print">Imprimir etiqueta</button></div><p class="help">El QR abre la ficha del activo en DammPulse. Los datos esenciales viajan en el enlace para abrirse desde otro móvil.</p></aside></div><div class="safety-note">Datos de demostración. No incluyas información confidencial ni procedimientos reales sin autorización.</div>'}
document.addEventListener("submit",e=>{if(e.target.id!=="qr-generator-form")return;e.preventDefault();const name=$("#qr-name").value.trim(),area=$("#qr-location").value.trim(),faults=$("#qr-faults").value.trim(),raw=$("#qr-code").value.trim().toUpperCase(),id=raw||("QR-"+Date.now().toString().slice(-7));if(machines.some(m=>m.id===id)){toast("Ese código ya existe. Introduce otro.");return}const m={id,name,area,line:"Activo QR",state:"Demo",owner:"Pendiente",docs:0,desc:"Ficha creada mediante el generador QR. Verificar con el responsable del activo.",function:"Pendiente de documentación aprobada.",systems:"Pendiente de confirmar.",check:"Consultar documentación oficial y responsable autorizado.",faults:faults||"Sin averías típicas documentadas."};machines.push(m);const saved=JSON.parse(localStorage.getItem("dp-custom-machines")||"[]");saved.push(m);localStorage.setItem("dp-custom-machines",JSON.stringify(saved));const params=new URLSearchParams({machine:id,name,location:area,faults:m.faults});const target=location.origin+location.pathname+"?"+params.toString()+"#asset-"+id;const image="https://api.qrserver.com/v1/create-qr-code/?size=420x420&margin=14&data="+encodeURIComponent(target);$("#qr-preview").innerHTML='<div class="qr-label"><div class="qr-label-top"><span>DAMMPULSE 360</span><span>ASSET ID / '+esc(id)+'</span></div><img id="generated-qr-image" src="'+image+'" alt="Código QR para '+esc(name)+'"><h3>'+esc(name)+'</h3><p>'+esc(area)+'</p><small>ESCANEA PARA ABRIR LA FICHA TÉCNICA</small></div>';$("#qr-result-actions").hidden=false;$("#qr-download").onclick=async()=>{try{const res=await fetch(image);const blob=await res.blob();const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="DammPulse-QR-"+id+".png";a.click();URL.revokeObjectURL(a.href)}catch(err){window.open(image,"_blank","noopener")}};$("#qr-print").onclick=()=>{const w=window.open("","_blank");if(!w){toast("Permite las ventanas emergentes para imprimir");return}w.document.write('<html><head><title>Etiqueta '+esc(id)+'</title><style>body{font-family:Arial;text-align:center;padding:28px;color:#16362c}.label{border:2px solid #16362c;border-radius:16px;padding:22px;max-width:340px;margin:auto}.label img{width:260px;height:260px}</style></head><body><div class="label"><strong>DAMMPULSE 360 · '+esc(id)+'</strong><br><img src="'+image+'"><h2>'+esc(name)+'</h2><p>'+esc(area)+'</p><small>ESCANEA PARA ABRIR LA FICHA</small></div></body></html>');w.document.close();w.onload=()=>w.print()};toast("QR generado correctamente")});


/* DAMTARIK SHIFT HUB — checklist y diario local de aprendizaje */
function academy(){
 const today=new Date().toLocaleDateString("en-CA");
 let state={};
 try{state=JSON.parse(localStorage.getItem("dt-shift-"+today)||"{}")}catch{}
 const tasks=[
  ["briefing","He revisado el briefing y las prioridades del turno."],
  ["safety","He identificado las normas y avisos de seguridad aplicables."],
  ["handover","He comprobado qué información necesita el siguiente turno."],
  ["learning","He reservado unos minutos para aprender algo nuevo."]
 ];
 const done=tasks.filter(t=>state[t[0]]).length;
 let notes=[];try{notes=JSON.parse(localStorage.getItem("dt-learning-notes")||"[]")}catch{}
 return head("PERSONAS / DESARROLLO","Academia Damtarik","Aprende, prepara tu jornada y deja constancia de lo que has descubierto.")+
 '<section class="shift-hero"><div><p class="eyebrow">SHIFT HUB · TU ESPACIO</p><h2>Un buen turno empieza con claridad.</h2><p>Una pequeña rutina para organizarte, compartir aprendizajes y cerrar el día con contexto.</p><span class="shift-date">'+new Date().toLocaleDateString("es-ES",{weekday:"long",day:"numeric",month:"long"})+'</span></div><div class="shift-score"><strong>'+done+'/4</strong><span>pasos completados</span><div class="shift-meter"><i style="width:'+(done*25)+'%"></i></div></div></section>'+
 '<div class="shift-layout"><section class="panel shift-check-panel"><div class="panel-head"><div><p>MI RUTINA</p><h2>Checklist de turno</h2></div><span class="tag amber">PERSONAL</span></div><p class="help">Marca cada paso cuando lo hayas revisado. Es una lista orientativa, no sustituye los procedimientos del centro.</p><div class="shift-checks">'+tasks.map(t=>'<label class="shift-check"><input type="checkbox" data-shift-check="'+t[0]+'" '+(state[t[0]]?'checked':'')+'><span class="shift-checkmark">✓</span><span>'+t[1]+'</span></label>').join("")+'</div><button class="btn small" data-shift-reset>Reiniciar checklist</button></section>'+
 '<section class="panel shift-note-panel"><div class="panel-head"><div><p>DIARIO DE APRENDIZAJE</p><h2>Una idea que me llevo</h2></div><span class="shift-note-icon">✎</span></div><form id="shift-note-form"><label class="field"><span>¿Qué has aprendido o qué conviene recordar?</span><textarea id="shift-note-text" maxlength="240" rows="4" required placeholder="Ej. He aprendido dónde consultar la ficha validada de un equipo…"></textarea></label><div class="shift-note-bottom"><small class="help">Máximo 240 caracteres · Guardado local</small><button class="btn primary small">Guardar nota</button></div></form></section></div>'+
 '<section class="panel shift-history"><div class="panel-head"><div><p>MI HISTORIAL</p><h2>Notas recientes</h2></div><span class="tag">'+notes.length+' guardadas</span></div>'+(notes.length?'<div class="shift-note-list">'+notes.slice(0,5).map(n=>'<article><span>'+esc(n.date)+'</span><p>'+esc(n.text)+'</p></article>').join("")+'</div>':'<div class="shift-empty"><span>✧</span><strong>Tu primera idea empieza aquí.</strong><small>Guarda una nota y aparecerá en este espacio.</small></div>')+'</section>'+
 '<div class="panel shift-lessons"><div class="panel-head"><div><p>MICROAPRENDIZAJE</p><h2>Continúa con tus módulos</h2></div></div><div class="learning-grid">'+lessons.map(l=>'<article class="lesson-card"><span class="tag">'+l.level+'</span><h3>'+l.title+'</h3><p>'+l.desc+'</p><div class="progress"><span style="width:'+(quizDone.has(l.id)?'100':'0')+'%"></span></div><div class="card-foot"><small class="help">'+l.time+' · Evaluación</small><button class="btn small primary" data-lesson="'+l.id+'">'+(quizDone.has(l.id)?'Repetir':'Comenzar')+' →</button></div></article>').join("")+'</div><div id="quiz-area"></div></section>'+
 '<div class="safety-note">Herramientas de organización personal para la demo. Los registros se guardan solo en este navegador y no se envían a sistemas de planta.</div>';
}
document.addEventListener("change",e=>{
 if(!e.target.matches("[data-shift-check]"))return;
 const today=new Date().toLocaleDateString("en-CA"),key="dt-shift-"+today;let state={};
 try{state=JSON.parse(localStorage.getItem(key)||"{}")}catch{}
 state[e.target.dataset.shiftCheck]=e.target.checked;localStorage.setItem(key,JSON.stringify(state));render();
});
document.addEventListener("click",e=>{
 if(!e.target.closest("[data-shift-reset]"))return;
 const today=new Date().toLocaleDateString("en-CA");localStorage.removeItem("dt-shift-"+today);toast("Checklist reiniciado");render();
});
document.addEventListener("submit",e=>{
 if(e.target.id!=="shift-note-form")return;
 e.preventDefault();const field=$("#shift-note-text"),value=field.value.trim();if(!value)return;
 let notes=[];try{notes=JSON.parse(localStorage.getItem("dt-learning-notes")||"[]")}catch{}
 notes.unshift({text:value,date:new Date().toLocaleString("es-ES")});localStorage.setItem("dt-learning-notes",JSON.stringify(notes.slice(0,30)));toast("Nota guardada en este navegador");render();
});
